import {validateSnapshot,circuitForProject,engineIdentity} from './domain.mjs';
import {drawCircuit} from '../wiring-generator/render.mjs';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function buildSheetModel(document){
 if(document.kind!=='TECHNICAL_BUILD_SHEET'||document.payload?.schema!==1)throw Error('Unsupported document.');
 const p=document.payload,s=validateSnapshot(p.snapshot,{allowHistorical:true});
 const diagram=s.engine===engineIdentity?drawCircuit(circuitForProject({version:1,electronics:s.electronics}),{exporting:true}):null;
 return {schema:1,id:document.id,project:document.project_id,revision:p.revision,generated:document.created_at,identity:s.metadata,summary:s.technical.summary,components:s.technical.components,limits:s.technical.limits,readiness:s.technical.readiness,measurements:p.measurements||[],electronics:s.electronics,diagram};
}
export function renderBuildSheet(model){
 const rows=model.components.map(c=>'<tr><td>'+escape(c.id)+'</td><td>'+escape(c.label)+'</td><td>'+escape(c.value)+'</td><td>DERIVED · logical requirement</td></tr>').join(''),measurements=model.measurements.map(m=>'<tr><td>'+escape(m.component_id||'Instrument')+'</td><td>'+escape(m.type)+'</td><td>'+escape(m.nominal??'Not recorded')+'</td><td>'+escape(m.value)+' '+escape(m.unit)+'</td><td>'+escape(m.observed_at)+' · MANUAL</td></tr>').join('');
 return '<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Technical Build Sheet</title><style>body{font:16px/1.5 system-ui;color:#222;background:#faf7ee;max-width:1050px;margin:24px auto;padding:20px}h1,h2{color:#222}table{border-collapse:collapse;width:100%;table-layout:fixed}td,th{padding:8px;border:1px solid #aaa;text-align:left;overflow-wrap:anywhere}svg{width:100%;height:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere}section{margin-block:24px}@media print{body{background:white;margin:0;padding:0}tr{break-inside:avoid}h2{break-after:avoid}}</style></head><body><header><p>APPARITION / FORGE · TECHNICAL BUILD SHEET</p><h1>'+escape(model.identity.title)+'</h1><p>Project '+escape(model.project)+' · Revision '+escape(model.revision.sequence)+' '+escape(model.revision.name)+'</p><p>Document '+escape(model.id)+' · Generated '+escape(model.generated)+'</p></header><section><h2>Instrument · USER-ENTERED</h2><p>'+Object.entries(model.identity.instrument).filter(([,v])=>v!==''&&v!=null).map(([k,v])=>escape(k)+': '+escape(v)).join('<br>')+'</p><p>'+escape(model.identity.notes)+'</p></section><section><h2>Configuration · DERIVED</h2><p>'+escape(model.summary)+'</p><p>'+escape(model.limits)+'</p><h3>Circuit / control representation · DERIVED</h3>'+ (model.diagram||'<p>Historical engine differs. Captured settings remain below; diagram regeneration is unavailable.</p>')+'<h3>Circuit record · KNOWN SETTINGS</h3><pre>'+escape(JSON.stringify(model.electronics,null,2))+'</pre></section><section><h2>Logical components · DERIVED</h2><table><thead><tr><th>Instance</th><th>Component</th><th>Specified value</th><th>Evidence</th></tr></thead><tbody>'+rows+'</tbody></table><p>Not a purchase order. Price, stock, dimensions and installation materials are not inferred.</p></section><section><h2>Bench measurements · MEASURED / USER-ENTERED</h2><table><thead><tr><th>Association</th><th>Type</th><th>Nominal (same unit)</th><th>Measured</th><th>Recorded</th></tr></thead><tbody>'+measurements+'</tbody></table><p>Manual readings are not independently verified. Pickup DCR does not establish output or tonal quality.</p></section><section><h2>Readiness / limits</h2><p>'+Object.entries(model.readiness).map(([k,v])=>escape(k)+': '+escape(v)).join('<br>')+'</p><p>Physical fit UNKNOWN. Geometry and manufacturing NOT MODELLED. No installation or CNC approval is implied.</p></section></body></html>';
}
